/*
 * A045954  Even-Lucky-Numbers: generated by a sieve process like that for
 *          Lucky numbers but starting with even numbers.
 * https://oeis.org/A045954
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nice, nonn, easy
 * Formula:   a(n) = n-th Even‑Lucky number – generated by a sieve * starting
 *            with the even numbers 2,4,6,8,… and removing every * k‑th
 *            surviving number where k is the next surviving even * number.
 *            This implementation keeps a static cache of already * computed
 *            terms and extends it on demand
 * Range:     u8 n <= 51, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   alloc_seq_array, free_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* required helpers (included by the test harness) */
#include "../utils/alloc_seq_array.h"
#include "../utils/free_seq.h"
#include <stddef.h>   /* for size_t */

/* return the n‑th Even‑Lucky number */
seq_t a(idx_t n)
{
    static seq_t *survivors = NULL;    /* cached survivors */
    static size_t survivors_len = 0;   /* number of cached survivors */

    /* index 0 is unused – sequence is 1‑based */
    if (n <= 0) return 0;

    /* already computed? */
    if ((size_t)n <= survivors_len) {
        return survivors[n - 1];
    }

    /* need more terms – estimate number of even inputs */
    size_t need   = (size_t)n;
    size_t m      = need * 15;          /* heuristic upper bound */
    if (m < 16) m = 16;

    /* recompute until we have at least 'need' survivors */
    while (1) {
        /* create the list of the first m even numbers */
        seq_t *list = alloc_seq_array(m);
        for (size_t i = 0; i < m; ++i) {
            list[i] = (seq_t)(2 * (i + 1));
        }
        size_t len = m;

        /* sieve: remove every step‑th element where step is the
         * current surviving even number.  Stop when step > len. */
        size_t i = 1;                    /* start at the second element */
        while (i < len) {
            size_t step = (size_t)list[i];
            if (step > len) break;

            size_t write = 0;
            for (size_t read = 0; read < len; ++read) {
                if ((read + 1) % step != 0) {   /* keep this element */
                    list[write++] = list[read];
                }
            }
            len = write;                      /* new length after removal */
            ++i;                               /* next survivor becomes step */
        }

        /* keep survivors if enough, otherwise enlarge the bound */
        if (len >= need) {
            free_seq(survivors);               /* free previous cache */
            survivors      = list;             /* new cache */
            survivors_len  = len;
            break;
        } else {
            free_seq(list);                    /* try a larger bound */
            m <<= 1;                            /* double the bound */
        }
    }

    return survivors[n - 1];
}
